mkdir -p /tmp/probe-xcheck && cat > /tmp/probe-xcheck/lib.js <<'EOF'
const {spawnSync} = require('child_process');
const BIN = '/workspace/dataset/test4_executable';
function run(val){
  const r = spawnSync(BIN, ['--a', val], {encoding:'buffer'});
  return {out: r.stdout?Buffer.from(r.stdout):Buffer.alloc(0),
          err: r.stderr?r.stderr.toString():'',
          code: r.status, sig: r.signal, error: r.error?String(r.error):null};
}
// raw-byte variant: pass exact bytes via /bin/sh octal printf (no NUL, no trailing LF)
function runRaw(buf){
  const oct = [...buf].map(b=>'\\'+b.toString(8).padStart(3,'0')).join('');
  const r = spawnSync('/bin/sh', ['-c', `exec "$0" --a "$(printf '${oct}')"`, BIN], {encoding:'buffer'});
  return {out: r.stdout?Buffer.from(r.stdout):Buffer.alloc(0),
          err: r.stderr?r.stderr.toString():'', code: r.status};
}
const hex = b => Buffer.from(b).toString('hex');
module.exports = {run, runRaw, hex, BIN};
EOF
cd /tmp/probe-xcheck && node -e '
const {run,hex}=require("/tmp/probe-xcheck/lib.js");
const cases=[["a__b","615f5f62"],["___","5f5f5f"],["_","5f"],["a_b","615f62"],["a\\b","615c62"],["\\\\","5c5c"],["a\\!\\b","615c215c62"],["!!abc!!","6121216162632121"],["","(empty)"],["A_B","415f42"]];
for(const [s] of cases){const r=run(s);console.log(JSON.stringify(s).padEnd(14), "in="+hex(Buffer.from(s,"utf8")).padEnd(16), "out="+hex(r.out).padEnd(20), "code="+r.code, r.err.trim()?("ERR:"+r.err.trim()):"");}
'

cd /tmp/probe-xcheck && node -e '
const {run,hex}=require("/tmp/probe-xcheck/lib.js");
const sep=[],notsep=[],weird=[];
for(let c=1;c<=0x7f;c++){
  const s="a"+String.fromCharCode(c)+String.fromCharCode(c)+"b";
  const r=run(s);
  const o=hex(r.out);
  if(r.code!==0){weird.push([c,"exit"+r.code,r.err.trim().slice(0,80)]);continue;}
  const expectSep="615f620a";                       // a_b
  const expectLit=hex(Buffer.from(s,"utf8"))+"0a";  // aCCb
  if(o===expectSep) sep.push(c);
  else if(o===expectLit) notsep.push(c);
  else weird.push([c,o]);
}
console.log("SEP count",sep.length);
console.log("SEP hex:",sep.map(c=>c.toString(16).padStart(2,"0")).join(" "));
console.log("SEP chars:",JSON.stringify(sep.map(c=>String.fromCharCode(c)).join("")));
console.log("WEIRD:",JSON.stringify(weird));
console.log("NOTSEP printable-punct:",notsep.filter(c=>c>0x20&&c<0x7f&&!/[0-9a-zA-Z]/.test(String.fromCharCode(c))).map(c=>c.toString(16)).join(" "));
'
